<?php require dirname(__DIR__, 2) . '/src/common.php'; begin_api(['POST']); try { require_auth(); $body=require_json_body(); $current=$body['currentPassword']??null; $next=$body['newPassword']??null; $record=read_json(path_private('auth.json')); if (!is_string($current)||!is_string($next)||strlen($next)<12||$current===$next||!password_verify($current,$record['passwordHash']??'')) api_error(422,'PASSWORD_CHANGE_REJECTED'); $record['passwordHash']=password_hash($next,PASSWORD_DEFAULT); atomic_json(path_private('auth.json'),$record); revoke_all_tokens(); json_response(200,['passwordChanged'=>true]); } catch (Throwable) { api_error(500,'PASSWORD_CHANGE_FAILED'); }
